"""Checks for the live-data map filters mockup (python3 -I test_lm.py live_map_filters_mockup.html shots/). A fresh page per width, 1440 and 390 px."""
import os, sys
from playwright.sync_api import sync_playwright
PAGE = 'file://' + os.path.abspath(sys.argv[1]); SHOTS = sys.argv[2]; os.makedirs(SHOTS, exist_ok=True)
fails, n = [], 0
def ok(c, what):
    global n; n += 1
    if not c: fails.append(what); print('FAIL', what)
IDX = "(nm) => itGraphGet().at.get(it.names.byLower.get(nm.toLowerCase()))"
def page(p, w, h):
    b = p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    pg = b.new_page(viewport={'width': w, 'height': h}, has_touch=w < 600, is_mobile=w < 600); errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto(PAGE); pg.wait_for_function('window.__MKREADY || window.__MKERR', timeout=60000)
    ok(not pg.evaluate('window.__MKERR'), f'{w}: boot ' + str(pg.evaluate('window.__MKERR')))
    pg.evaluate("itm.box.scrollIntoView({block:'start'})"); pg.wait_for_timeout(300)
    return b, pg, errs
def shot(pg, w, name): pg.evaluate("itm.box.scrollIntoView({block:'start'})"); pg.wait_for_timeout(250); pg.screenshot(path=os.path.join(SHOTS, f'{w}_{name}.png'))
def press(pg, k, phone):
    if phone and not pg.evaluate("!!document.querySelector('.it-map-fb.open')"): pg.evaluate("document.querySelector('.it-map-fcur').click()"); pg.wait_for_timeout(150)
    pg.evaluate(f"document.querySelector('[data-im-f=\"{k}\"]').click()"); pg.wait_for_timeout(200)
with sync_playwright() as p:
    for w, h in [(1440, 900), (390, 844)]:
        phone = w < 600
        b, pg, errs = page(p, w, h)
        # 1. the column: the four new filters in their groups, in order
        keys = pg.evaluate("[...document.querySelectorAll('.it-map-fbtns [data-im-f]')].map(b => b.dataset.imF)")
        ok(keys == ['sec', 'jumps', 'region', 'sovh', 'jumph', 'killh', 'secr', 'near', 'reports', 'kills', 'wh', 'sov', 'regpick', 'paths'], f'{w}: column order {keys}')
        grp = pg.evaluate("[...document.querySelectorAll('.it-map-fbtns .mk-fg')].map(g => [g.className.split(' ').pop(), g.querySelectorAll('[data-im-f]').length])")
        ok(grp == [['mk-fg-colour', 6], ['mk-fg-only', 7], ['mk-fg-view', 1]], f'{w}: groups {grp}')
        names = pg.evaluate("['sovh','jumph','killh','regpick'].map(k => document.querySelector(`[data-im-f=${k}]`).getAttribute('aria-label'))")
        ok(names == ['Sov holder', 'Jumps (past hour)', 'Kills (past hour)', 'Region pick'], f'{w}: names {names}')
        ok(pg.evaluate("['sovh','killh','regpick'].every(k => document.querySelector(`[data-it-mpn=${k}]`)) && !document.querySelector('[data-it-mpn=jumph]')"), f'{w}: settings buttons for Sov holder, Kills (past hour), Region pick; none for Jumps (past hour)')
        # soft colour: a bit up by default, Today and More differ (zoomed out and zoomed in)
        sv = pg.evaluate("(() => { const i = itMapTable().adj[itm.home][0], out = {}; for(const k of ['today', 'up', 'more']){ MKL.soft = k; out[k] = [itMapFcol(i), itMapMix('#4f8fe0', 0.38)]; } MKL.soft = 'more'; return out; })()")
        ok(sv['today'] != sv['up'] != sv['more'] and sv['today'][1] != sv['up'][1], f'{w}: soft colour steps differ {sv}')
        ok(pg.evaluate("MKL.soft") == 'more', f'{w}: soft colour More by default (the owner\'s pick)')
        ok(pg.evaluate("itMapMix('#4f8fe0', 0.55) === itMapMix('#4f8fe0', 0.8) && itMapMix('#4f8fe0', 0.38) !== itMapMix('#4f8fe0', 0.5)"), f'{w}: More keeps 80% zoomed out')
        # 2. Sov holder by standing (the boot scene)
        ok(pg.evaluate("itMapSt().colour") == 'sovh' and pg.evaluate("document.querySelector('[data-im-f=sovh]').getAttribute('aria-pressed')") == 'true', f'{w}: Sov holder on and pressed')
        cols = pg.evaluate(f"(() => {{ const I = {IDX}; return [itMapColRaw(itm.home), itMapColRaw(I('MSG-BZ'))]; }})()")
        ok(cols == ['#4f8fe0', '#c65b4e'], f'{w}: yours blue, the Raiders hostile red {cols}')
        npc = pg.evaluate("(() => { const T = itMapTable(); for(let i = 0; i < T.n; i++) if(itMapSecT(i) >= 5) return [MKL.holderOf(i), itMapColRaw(i)]; })()")
        ok(npc == [-2, '#7a6f58'], f'{w}: high-sec is NPC faction space, muted {npc}')
        ok(pg.evaluate("(() => { const T = itMapTable(); let u = 0; for(let i = 0; i < T.n; i++) if(MKL.holderOf(i) === -1){ u++; if(itMapColRaw(i) !== '#56616b') return false; } return u > 0; })()"), f'{w}: unclaimed systems plain')
        leg = pg.evaluate("itm.el.querySelector('.it-map-leg .it-map-fl').textContent")
        ok('Sov holder' in leg and 'hostile' in leg and 'unclaimed' in leg, f'{w}: legend by standing: {leg}')
        hv = pg.evaluate("(itm.el.querySelector('.it-map-leg .mk-hv') || {}).textContent || ''")
        ok('In view' in hv and 'MKCO' in hv, f'{w}: holders in view with logos: {hv}')
        ok(pg.evaluate("itm.el.querySelectorAll('.it-map-leg .mk-hv img').length") >= 1, f'{w}: in-view list has logos')
        # gate lines only between two systems of one holder
        ok(pg.evaluate("MKL.edges.every((E, h) => { for(let e = 0; e < E.length; e += 2) if(MKL.H[E[e]] !== h || MKL.H[E[e + 1]] !== h) return false; return true; }) && MKL.edges[0].length > 0"), f'{w}: holder lines: same holder at both ends')
        shot(pg, w, '01_sov_standing')
        # 3. zoomed in: logos in the circles (none zoomed out), the hover
        pg.evaluate("MKL.logoDraws = 0; itMapDraw()"); ok(pg.evaluate("MKL.logoDraws") == 0, f'{w}: zoomed out, no logos')
        pg.evaluate("MKL.scene('zoomin')"); pg.wait_for_timeout(300)
        pg.evaluate("MKL.logoDraws = 0; itMapDraw()"); ok(pg.evaluate("MKL.logoDraws") > 5, f'{w}: zoomed in, logos in the circles ({pg.evaluate("MKL.logoDraws")})')
        ok(pg.evaluate("itm.stage") >= 1, f'{w}: zoomed in (circles)')
        if not phone:
            xy = pg.evaluate(f"(() => {{ const i = ({IDX})('MSG-BZ'), r = itm.cv.getBoundingClientRect(); return [r.left + itm.Q[2*i], r.top + itm.Q[2*i+1]]; }})()")
            pg.mouse.move(xy[0], xy[1]); pg.wait_for_timeout(300)
            tip = pg.evaluate("itm.tip.hidden ? '' : itm.tip.textContent")
            ok('Mockup Raiders' in tip and 'Military' in tip and 'ADM' in tip and 'vulnerable' in tip and 'capital' in tip, f'{w}: hover names holder, levels, ADM, window, capital: {tip[:160]}')
            shot(pg, w, '02_sov_zoomed_hover'); pg.mouse.move(5, 5)
        else: shot(pg, w, '02_sov_zoomed')
        pg.evaluate("MKL.logos = false; MKL.logoDraws = 0; itMapDraw()"); ok(pg.evaluate("MKL.logoDraws") > 5, f'{w}: logos not loaded: circles still drawn (tickers)')
        shot(pg, w, '03_sov_tickers'); pg.evaluate("MKL.logos = true; MKL.ring = 'disc'; itMapDraw()"); shot(pg, w, '04_sov_disc'); pg.evaluate("MKL.ring = 'ring'; itMapDraw()")
        # 4. per alliance: neighbours differ
        pg.evaluate("MKL.scene('alliance')"); pg.wait_for_timeout(200)
        ok(pg.evaluate("(() => { const T = itMapTable(), H = MKL.H; for(let i = 0; i < T.n; i++) for(const j of T.adj[i]) if(H[i] >= 0 && H[j] >= 0 && H[i] !== H[j] && MKL.allCol[H[i]] === MKL.allCol[H[j]]) return false; return true; })()"), f'{w}: per alliance, neighbouring holders differ')
        ok(pg.evaluate("MKL.allCol.every(c => !['#4fc3d9', '#d99a3c', '#9b7bd8', '#c98fd0'].includes(c))"), f'{w}: per alliance keeps the reserved hues')
        ok('one per alliance' in pg.evaluate("itm.el.querySelector('.it-map-leg .it-map-fl').textContent"), f'{w}: legend per alliance')
        shot(pg, w, '05_sov_alliance')
        # 5. the settings panel switches by standing / per alliance
        if phone: press(pg, 'sovh', True); press(pg, 'sovh', True)
        pg.evaluate("itMpOpen('sovh')"); pg.wait_for_timeout(200)
        ok(pg.evaluate("itMpShown() && itMp.k === 'sovh'"), f'{w}: Sov holder settings open')
        pg.evaluate("itMp.el.querySelector('input[value=standing]').click()"); pg.wait_for_timeout(150)
        ok(pg.evaluate("itMapSt().sovBy") == 'standing', f'{w}: the panel switches back to standing')
        pg.evaluate("itMpOpen('', false)")
        # 6. one colour at a time
        pg.evaluate("itMapFilterSet('jumph')")
        ok(pg.evaluate("itMapSt().colour") == 'jumph' and pg.evaluate("document.querySelector('[data-im-f=sovh]').getAttribute('aria-pressed')") == 'false', f'{w}: Jumps (past hour) replaces Sov holder')
        ok(pg.evaluate("itMapColRaw(itm.home)") in ['#2a3640', '#2f5d63', '#3f8a83', '#6fb59a', '#b8d88a', '#f0f0b0'], f'{w}: jumps scale colour')
        steps = pg.evaluate("(() => { const T = itMapTable(), out = new Set(); for(let i = 0; i < T.n; i++){ const j = MKL.jumps[i], c = itMapColRaw(i), k = j >= 500 ? 5 : j >= 150 ? 4 : j >= 50 ? 3 : j >= 10 ? 2 : j >= 1 ? 1 : 0; if(c !== ['#2a3640', '#2f5d63', '#3f8a83', '#6fb59a', '#b8d88a', '#f0f0b0'][k]) return -1; out.add(k); } return out.size; })()")
        ok(steps == 6, f'{w}: jumps steps 0 / 1–9 / 10–49 / 50–149 / 150–499 / 500+ all used and right ({steps})')
        jl = pg.evaluate("itm.el.querySelector('.it-map-leg .it-map-fl').textContent"); ok('Jumps (past hour)' in jl and 'as of' in jl, f'{w}: jumps legend {jl}')
        ok(pg.evaluate("!itm.el.querySelector('.it-map-leg .mk-hv')"), f'{w}: no holders list off Sov holder')
        ok(pg.evaluate("window.__MKnofade()") and not any(x in pg.evaluate("itm.el.querySelector('.it-map-leg').textContent") for x in ['faint: past', 'faded: past']), f'{w}: Q10: no fade with Jumps (past hour), legend drops faded/faint')
        pg.evaluate("MKL.scene('today')"); pg.wait_for_timeout(150)
        ok(not pg.evaluate("window.__MKnofade()") and 'faint: past' in pg.evaluate("itm.el.querySelector('.it-map-leg').textContent"), f'{w}: Q10: Security keeps today\'s fade and legend')
        pg.evaluate("itMapFilterSet('jumph')"); pg.wait_for_timeout(150)
        shot(pg, w, '06_jumps')
        pg.evaluate("MKL.scene('jumpsin')"); pg.wait_for_timeout(200); shot(pg, w, '07_jumps_zoomed')
        # 7. kills, and NPC kills from its settings
        pg.evaluate("MKL.scene('kills')"); pg.wait_for_timeout(200)
        ok(pg.evaluate(f"itMapColRaw(({IDX})('78-0R6'))") != '#2a3640', f'{w}: kills where the reports are')
        pg.evaluate("itMpOpen('killh')"); pg.wait_for_timeout(150)
        pg.evaluate("itMp.el.querySelector('input[value=npc]').click()"); pg.wait_for_timeout(150)
        ok(pg.evaluate("itMapSt().killNpc") is True and 'NPC kills' in pg.evaluate("itm.el.querySelector('.it-map-leg .it-map-fl').textContent"), f'{w}: NPC kills from the panel, legend says so')
        shot(pg, w, '08_npc_kills'); pg.evaluate("itMpOpen('', false)")
        # 8. Region pick: opens its list when switched on with none picked; any pick counts; Clear; search
        pg.evaluate("MKL.scene('today')")
        press(pg, 'regpick', phone)
        ok(pg.evaluate("itMpShown() && itMp.k === 'regpick'"), f'{w}: Region pick opens its list the first time')
        ok(pg.evaluate("itMapMatch() ? itMapMatch().list.length : -1") == 0, f'{w}: none picked: nothing matches but you')
        nreg = pg.evaluate("itMp.el.querySelectorAll('[data-mk-reg]').length"); ok(nreg == pg.evaluate("new Set(Array.from(itMapTable().reg)).size"), f'{w}: a box per region ({nreg})')
        mine = pg.evaluate("itMapTable().regions[itMapTable().reg[itm.home]]")
        ok(pg.evaluate("itMp.el.querySelector('[data-mk-reg]').dataset.mkReg") == mine, f'{w}: your region first')
        pg.evaluate(f"itMp.el.querySelector('[data-mk-reg=\"{mine}\"]').click()"); pg.wait_for_timeout(200)
        cnt = pg.evaluate("(() => { const T = itMapTable(), r = T.reg[itm.home]; let k = 0; for(let i = 0; i < T.n; i++) if(T.reg[i] === r && i !== itm.home) k++; return k; })()")
        ok(pg.evaluate("itMapMatch().list.length") == cnt, f'{w}: your region matches its {cnt} systems')
        pg.evaluate("const q = itMp.el.querySelector('.mk-rq'); q.value = 'cloud'; q.dispatchEvent(new Event('input', {bubbles: true}))"); pg.wait_for_timeout(100)
        vis = pg.evaluate("[...itMp.el.querySelectorAll('[data-mk-r]')].filter(l => !l.hidden).map(l => l.textContent.trim())")
        ok(len(vis) == 1 and vis[0].startswith('Cloud Ring'), f'{w}: search narrows the list {vis}')
        pg.evaluate("itMp.el.querySelector('[data-mk-reg=\"Cloud Ring\"]').click()"); pg.wait_for_timeout(200)
        ok(pg.evaluate("itMapMatch().list.length") > cnt, f'{w}: a second region adds its systems')
        only = pg.evaluate("(itm.el.querySelector('.it-map-leg .it-map-only') || {}).textContent || ''"); ok(f'in {mine}, Cloud Ring' in only, f'{w}: Only line names the regions: {only}')
        pg.evaluate("const q = itMp.el.querySelector('.mk-rq'); q.value = ''; q.dispatchEvent(new Event('input', {bubbles: true}))")
        ok(pg.evaluate("(() => { const a = itMp.el.querySelector('[data-mk-rall]'); return a.indeterminate && !a.checked; })()"), f'{w}: Select all shows a dash with some picked')
        ok(pg.evaluate("getComputedStyle(itMp.el.querySelector('[data-mk-rall]'), '::before').visibility") == 'visible', f'{w}: the dash is drawn')
        shot(pg, w, '09_region_pick')
        # Select all: every region; untick: none; with a search, only the regions shown
        allr = pg.evaluate("new Set(Array.from(itMapTable().reg)).size")
        pg.evaluate("itMp.el.querySelector('[data-mk-rall]').click()"); pg.wait_for_timeout(150)
        ok(pg.evaluate("itMapSt().regions.length") == allr and pg.evaluate("itMapMatch().list.length") == pg.evaluate("itMapTable().n") - 1, f'{w}: Select all picks every region; every system matches')
        ok(pg.evaluate("itMp.el.querySelector('[data-mk-rall]').checked && [...itMp.el.querySelectorAll('[data-mk-reg]')].every(b => b.checked)"), f'{w}: Select all ticks every box')
        shot(pg, w, '09b_region_all')
        pg.evaluate("itMp.el.querySelector('[data-mk-rall]').click()"); pg.wait_for_timeout(150)
        ok(pg.evaluate("itMapSt().regions.length") == 0, f'{w}: unticking Select all picks none')
        pg.evaluate("const q = itMp.el.querySelector('.mk-rq'); q.value = 'de'; q.dispatchEvent(new Event('input', {bubbles: true}))"); pg.wait_for_timeout(100)
        shown = pg.evaluate("[...itMp.el.querySelectorAll('[data-mk-r]')].filter(l => !l.hidden).map(l => l.querySelector('input').dataset.mkReg)")
        ok(pg.evaluate("itMp.el.querySelector('.mk-rall-t').textContent") == 'Select all shown', f'{w}: with a search it says Select all shown')
        pg.evaluate("itMp.el.querySelector('[data-mk-rall]').click()"); pg.wait_for_timeout(150)
        ok(sorted(pg.evaluate("itMapSt().regions")) == sorted(shown) and len(shown) >= 2, f'{w}: Select all shown picks only the regions shown {shown}')
        pg.evaluate("const q = itMp.el.querySelector('.mk-rq'); q.value = ''; q.dispatchEvent(new Event('input', {bubbles: true})); itMapSt().regions = ['" + mine + "', 'Cloud Ring']; for(const b of itMp.el.querySelectorAll('[data-mk-reg]')) b.checked = itMapSt().regions.includes(b.dataset.mkReg); itMpChanged()"); pg.wait_for_timeout(150)
        # stacked with Security range
        pg.evaluate("itMpOpen('', false); const s = itMapSt(); s.only.secr = true; s.secr = {lo: -10, hi: -5}; MKL.apply()")
        ok(pg.evaluate("itMapMatch().list.every(i => itMapSecT(i) <= -5 && (itMapTable().regions[itMapTable().reg[i]] === 'Cloud Ring' || itMapTable().reg[i] === itMapTable().reg[itm.home]))"), f'{w}: Region pick stacks with Security range')
        pg.evaluate("itMapSt().only.secr = false; MKL.apply()")
        # kept: the stack's new fields read back; an unknown region dropped
        back = pg.evaluate("(() => { itMapStackSave(); const s = JSON.parse(localStorage.getItem(MAP_STACK_KEY)); s.regions.push('Nowhere Mockup'); localStorage.setItem(MAP_STACK_KEY, JSON.stringify(s)); const o = itMapStackRead(); return [o.regions, o.only.regpick, o.killNpc, o.sovBy]; })()")
        ok(back[0] == [mine, 'Cloud Ring'] and back[1] is True, f'{w}: picks kept, unknown region dropped {back}')
        pg.evaluate("itMp.el.querySelector('[data-mk-rclr]') && itMpOpen('regpick')"); pg.wait_for_timeout(100)
        pg.evaluate("itMpOpen('regpick'); itMp.el.querySelector('[data-mk-rclr]').click()"); pg.wait_for_timeout(150)
        ok(pg.evaluate("itMapSt().regions.length") == 0 and pg.evaluate("itMapMatch().list.length") == 0, f'{w}: Clear: none picked, nothing matches')
        pg.evaluate("itMpOpen('', false)")
        # 9. the phone column by group; nothing moves when a settings button shows
        if phone:
            pg.evaluate("MKL.scene('today'); itMapFbarOpen(true)"); pg.wait_for_timeout(250)
            r = pg.evaluate("(() => { const q = (s) => document.querySelector(s).getBoundingClientRect(); const c = q('.mk-fg-colour'), o = q('.mk-fg-only'), v = q('.mk-fg-view'), m = itm.box.getBoundingClientRect(); return {c: [c.left, c.right, c.top, c.bottom], o: [o.left, o.right, o.top, o.bottom], v: [v.left, v.right, v.top, v.bottom], mb: m.bottom, mr: m.right}; })()")
            ok(r['o'][0] >= r['c'][1] - 1, f'{w}: Only in its own column right of Colour {r}')
            ok(r['v'][2] >= r['c'][3] - 1 and abs(r['v'][0] - r['c'][0]) < 2, f'{w}: View under Colour')
            ok(max(r['c'][3], r['o'][3], r['v'][3]) <= r['mb'] and r['o'][1] <= r['mr'], f'{w}: the column fits in the map')
            x0 = pg.evaluate("document.querySelector('.mk-fg-only').getBoundingClientRect().left")
            press(pg, 'sovh', True); pg.wait_for_timeout(200)
            if not pg.evaluate("!!document.querySelector('.it-map-fb.open')"): pg.evaluate("itMapFbarOpen(true)"); pg.wait_for_timeout(200)
            ok(pg.evaluate("getComputedStyle(document.querySelector('[data-it-mpn=sovh]')).display") != 'none', f'{w}: Sov holder settings button shows while on')
            x1 = pg.evaluate("document.querySelector('.mk-fg-only').getBoundingClientRect().left")
            ok(abs(x1 - x0) < 1, f'{w}: the Only column doesn\'t move when a settings button shows ({x0} -> {x1})')
            ok(pg.evaluate("[...document.querySelectorAll('.it-map-fbtns [data-im-f]')].every(b => b.getBoundingClientRect().height >= 44)"), f'{w}: 44 px buttons')
            shot(pg, w, '10_phone_column')
            pg.evaluate("MKL.grouped = false; MKL.remake(); itMapFbarOpen(true)"); pg.wait_for_timeout(200); shot(pg, w, '11_phone_column_today')
            pg.evaluate("MKL.grouped = true; MKL.remake(); itMapFbarOpen(false)")
        else:
            ok(pg.evaluate("getComputedStyle(document.querySelector('.mk-fg-only')).display") == 'contents', f'{w}: desktop column unchanged (groups are display:contents)')
            rows = pg.evaluate("getComputedStyle(document.querySelector('.it-map-fbtns')).getPropertyValue('--it-flr')")
            ok(rows.strip() == '16', f'{w}: column rows count the 14 filters and 2 lines ({rows})')
        ok(pg.evaluate("document.documentElement.scrollWidth <= innerWidth"), f'{w}: no sideways scroll')
        ok(not errs, f'{w}: no page errors {errs[:2]}')
        b.close()
print(f'{n - len(fails)} of {n} passed'); sys.exit(1 if fails else 0)
